// One request per (country x search term), capped so the free API quota lasts.
// Edit ADZUNA_COUNTRIES / ADZUNA_QUERIES in .env - no workflow change needed.
const DEFAULT_COUNTRIES = 'de,at,ch,nl,fr,gb,pl,es,it';
const countries = ($env.ADZUNA_COUNTRIES || DEFAULT_COUNTRIES)
  .split(',')
  .map((c) => c.trim().toLowerCase())
  .filter(Boolean);

const queries = ($env.ADZUNA_QUERIES || $env.ADZUNA_QUERY || 'software engineer')
  .split(',')
  .map((q) => q.trim())
  .filter(Boolean);

const cap = Number($env.ADZUNA_MAX_REQUESTS || 12);

const combos = [];
// Term-major, so if the cap bites it drops extra search terms before it drops countries.
for (const what of queries) {
  for (const country of countries) {
    combos.push({ country, what });
  }
}

if (!combos.length) {
  return [{ json: { empty: true, note: 'ADZUNA_COUNTRIES / ADZUNA_QUERIES are empty' } }];
}

return combos.slice(0, cap).map((c) => ({
  json: {
    country: c.country,
    what: c.what,
    url:
      'https://api.adzuna.com/v1/api/jobs/' + c.country + '/search/1' +
      '?app_id=' + encodeURIComponent($env.ADZUNA_APP_ID || '') +
      '&app_key=' + encodeURIComponent($env.ADZUNA_APP_KEY || '') +
      '&results_per_page=50' +
      '&max_days_old=30' +
      '&sort_by=date' +
      '&category=it-jobs' +
      '&content-type=application/json' +
      '&what=' + encodeURIComponent(c.what),
  },
}));

// One HTTP result per requested country, in order. Correlate by index so each
// row knows which country's feed it came from - the API does not echo it back.
const queries = $('Build country queries').all();
const items = $input.all();

function text(v) { return v === null || v === undefined ? '' : String(v); }
function clean(s) {
  return text(s).replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
function fixMojibake(s) {
  if (!/[\u00C2\u00C3\u00E2][\u0080-\u00BF]/.test(s)) return s;
  try {
    const repaired = Buffer.from(s, 'latin1').toString('utf8');
    if (!repaired.includes('\uFFFD') && !/[\u00C2\u00C3\u00E2][\u0080-\u00BF]/.test(repaired)) return repaired;
  } catch (e) { /* keep original */ }
  return s;
}
function fingerprint(company, title, location) {
  const norm = (v) => text(v).toLowerCase()
    .replace(/\b(inc|llc|ltd|pvt|private|limited|corp|corporation|technologies|solutions|labs|gmbh|ag|sa|bv|srl|sarl)\b/g, '')
    .replace(/[^a-z0-9]+/g, ' ').trim();
  const base = [norm(company), norm(title), norm(location)].join('|');
  try {
    const crypto = require('crypto');
    return crypto.createHash('sha256').update(base).digest('hex').slice(0, 32);
  } catch (e) {
    let h = 2166136261;
    for (let i = 0; i < base.length; i++) { h ^= base.charCodeAt(i); h = Math.imul(h, 16777619); }
    return 'fnv' + (h >>> 0).toString(16) + base.length;
  }
}

const out = [];
for (let idx = 0; idx < items.length; idx++) {
  const j = items[idx].json || {};
  const meta = (queries[idx] && queries[idx].json) || {};

  // A failed country (bad code, quota) arrives as an error object; skip it.
  if (j.error) continue;

  const results = Array.isArray(j.results) ? j.results : Array.isArray(j) ? j : [];
  for (const r of results) {
    const title = fixMojibake(clean(r.title));
    const company = fixMojibake(clean(r.company && (r.company.display_name || r.company)));
    const location = fixMojibake(clean(r.location && (r.location.display_name || r.location)));
    if (!title || !company) continue;

    const salary = r.salary_min || r.salary_max
      ? text(r.salary_min) + '-' + text(r.salary_max) + ' ' + (String(r.salary_is_predicted) === '1' ? '(est.)' : '')
      : '';

    out.push({
      source: 'adzuna',
      external_id: text(r.id),
      title,
      company,
      location,
      country: meta.country || null,
      url: text(r.redirect_url),
      description: fixMojibake(clean(r.description)),
      salary_text: salary,
      tags: r.category && r.category.label ? [clean(r.category.label)] : [],
      posted_at: r.created || null,
      fingerprint: fingerprint(company, title, location),
    });
  }
}

if (!out.length) {
  return [{ json: { empty: true, note: 'Adzuna returned no usable results for these countries/terms' } }];
}
return out.map((row) => ({ json: row }));

// One INSERT per 75 rows, with ON CONFLICT DO NOTHING so re-running the
// workflow is safe (idempotency lives in the database, not in the code).
const items = $input.all().map((i) => i.json).filter((r) => r && r.fingerprint);
if (!items.length) return [{ json: { rows: 0, sql: 'SELECT 1;' } }];

const esc = (v) =>
  v === null || v === undefined || v === ''
    ? 'NULL'
    : "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";

const jsonb = (v) =>
  "'" + JSON.stringify(Array.isArray(v) ? v : []).replace(/'/g, "''") + "'::jsonb";

const stamp = (v) => {
  if (!v) return 'NULL';
  const d = new Date(v);
  return isNaN(d.getTime()) ? 'NULL' : "'" + d.toISOString() + "'::timestamptz";
};

const CHUNK = 75;
const chunks = [];
for (let i = 0; i < items.length; i += CHUNK) chunks.push(items.slice(i, i + CHUNK));

return chunks.map((rows, idx) => ({
  json: {
    chunk: idx + 1,
    rows: rows.length,
    sql:
      'INSERT INTO jobs (source, external_id, title, company, location, country, url, description, salary_text, tags, fingerprint, posted_at) VALUES ' +
      rows
        .map(
          (r) =>
            '(' +
            [
              esc(r.source),
              esc(r.external_id),
              esc(r.title),
              esc(r.company),
              esc(r.location),
              // undefined for rows that carry no location (alert emails) -> NULL
              esc(r.country),
              esc(r.url),
              esc(r.description),
              esc(r.salary_text),
              jsonb(r.tags),
              esc(r.fingerprint),
              stamp(r.posted_at),
            ].join(',') +
            ')'
        )
        .join(',') +
      ' ON CONFLICT (fingerprint) DO NOTHING RETURNING id;',
  },
}));

const fetched = $('Normalise Adzuna').all().filter((i) => i.json && i.json.fingerprint).length;
const offered = $('Build SQL chunks').all().reduce((n, i) => n + (i.json.rows || 0), 0);
let inserted = 0;
for (const i of $input.all()) {
  const j = i.json || {};
  if (Array.isArray(j)) inserted += j.length;
  else if (Array.isArray(j.rows)) inserted += j.rows.length;
  else if (j.id !== undefined) inserted += 1;
}

const byCountry = {};
for (const i of $('Normalise Adzuna').all()) {
  const c = i.json && i.json.country;
  if (c) byCountry[c] = (byCountry[c] || 0) + 1;
}

return [{ json: {
  source: 'adzuna',
  countries_requested: $('Build country queries').all().length,
  fetched,
  unique_in_batch: offered,
  new_rows: inserted,
  duplicates_skipped: Math.max(offered - inserted, 0),
  by_country: byCountry,
} }];
